def analyze_land_regulation(pnu_or_address: str, input_type: str = "pnu", zones_json: str = "[]", include_law: bool = True) -> str:
    import requests, json
    try:
        zones = json.loads(zones_json) if zones_json else []
    except json.JSONDecodeError:
        zones = []
    payload = {"input": pnu_or_address, "input_type": input_type, "zones": zones, "include_law": include_law}
    try:
        resp = requests.post("http://127.0.0.1:8000/land/analyze/", json=payload, timeout=60)
        resp.raise_for_status()
        return json.dumps(resp.json(), ensure_ascii=False, indent=2)
    except requests.exceptions.ConnectionError:
        return json.dumps({"error": "ARR Django 서버 미실행 (http://127.0.0.1:8000)"}, ensure_ascii=False)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)

