def search_regulatory_changes(zone_type: str, regulation_area: str = "건폐율") -> str:
    import requests, json
    queries = [
        f"{zone_type} {regulation_area} 개정",
        f"{zone_type} 규제 완화",
        f"{zone_type} 용도변경"
    ]
    results = []
    for q in queries:
        try:
            resp = requests.post("http://127.0.0.1:8011/api/search", json={"query": q, "limit": 5}, timeout=30)
            if resp.ok:
                data = resp.json()
                results.append({"query": q, "results": data.get("results", [])})
        except Exception as e:
            results.append({"query": q, "error": str(e)})
    return json.dumps({"regulatory_changes": results}, ensure_ascii=False, indent=2)

def compare_zone_regulations(zone1: str, zone2: str = "") -> str:
    import requests, json
    try:
        resp = requests.get("http://127.0.0.1:8000/land/zones/", timeout=30)
        resp.raise_for_status()
        data = resp.json()
        zones = {z['zone_name']: z for z in data.get('zones', [])}
        result = {}
        if zone1 in zones:
            result['zone1'] = zones[zone1]
        else:
            result['zone1_error'] = f"'{zone1}' 미발견"
        if zone2 and zone2 in zones:
            result['zone2'] = zones[zone2]
            if zone1 in zones:
                z1, z2 = zones[zone1], zones[zone2]
                result['comparison'] = {
                    'bcr_diff': z1['bcr_default'] - z2['bcr_default'],
                    'far_diff': z1['far_default'] - z2['far_default'],
                    'stricter': zone1 if z1['bcr_default'] <= z2['bcr_default'] else zone2
                }
        return json.dumps(result, ensure_ascii=False, indent=2)
    except Exception as e:
        return json.dumps({"error": str(e)}, ensure_ascii=False)

